#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int dat = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 1) dat++;
    }
    printf("%d\n", (dat * 100) / n);
    return 0;
}
